INSERT INTO CLOUDWALK.ALERT_HANDLING_RECORD (
    ALERT_ID, HANDLER, HANDLE_TIME, HANDLE_RESULT, HANDLE_METHOD, REMARK
) VALUES (
    #{alertId}, #{handler}, #{handleTime}, #{handleResult}, #{handleMethod}, #{remark}
)

mapper.select:
SELECT 
FROM CLOUDWALK.ALERT_HANDLING_RECORD


        AND ALERT_ID = #{params.alertId}


        AND HANDLER = #{params.handler}


        AND HANDLE_RESULT = #{params.handleResult}


        AND HANDLE_METHOD = #{params.handleMethod}


        AND HANDLE_TIME >= #{params.startTime}


        AND HANDLE_TIME <= #{params.endTime}


ORDER BY CREATE_TIME DESC
OFFSET #{params.offset} ROWS FETCH NEXT #{params.limit} ROWS ONLY

SELECT COUNT(*)
FROM CLOUDWALK.ALERT_HANDLING_RECORD


        AND ALERT_ID = #{params.alertId}


        AND HANDLER = #{params.handler}


        AND HANDLE_RESULT = #{params.handleResult}


        AND HANDLE_METHOD = #{params.handleMethod}


        AND HANDLE_TIME >= #{params.startTime}


        AND HANDLE_TIME <= #{params.endTime}
